  /* --------------------------------------------------------------- шаблоны

     Документ описан набором блоков, а не сплошным текстом: шапка, реквизиты,
     абзацы, пункты, таблицы, подписи. Блоки собираются в HTML (экран, Word,
     печать) и в простой текст (буфер обмена, .txt).

     Блоки:  title/sub — шапка;  req — место и дата;  addr — адресат заявления;
             p/np — абзац с отступом и без;  h — подзаголовок;  c — по центру;
             ol/ul — списки;  tbl — таблица;  sig — подпись;  line — строка
             для записи от руки;  note — примечание;  br — разрыв страницы.

     Поля:   p — образец;  src:"today" — сегодняшняя дата;
             src:"profile.<ключ>" — из «Моих реквизитов» (заполняется один раз).
     ------------------------------------------------------------------------ */

